#!/usr/bin/env python3
"""
generate_loan_book_backend.py

Creates the complete Loan Book backend: 4 models, 4 repositories, the
service layer (Finance Engine-integrated), schemas, Flask API routes,
an Alembic migration, and 16 tests proving cross-business ownership
isolation at both the service layer and real HTTP/JWT stack.

REQUIRES MANUAL STEPS AFTERWARD -- see
backend/src/domains/business/loan_book/LOAN_BOOK_BACKEND_README.md
(created by this script): registering the blueprint in src/__init__.py,
verifying the migration's down_revision, and two other small
verifications flagged honestly rather than guessed.

Usage:
    python generate_loan_book_backend.py --root .
    python generate_loan_book_backend.py --root . --dry-run
    python generate_loan_book_backend.py --root . --force
"""

import argparse
import sys
from pathlib import Path

FILES: dict[str, str] = {}

FILES['backend/src/domains/business/loan_book/models/customer.py'] = '"""\nCustomer -- a person a business extends credit to. Matches the\nfrontend\'s types.ts Customer shape field-for-field.\n\nbusiness_id is the OWNERSHIP field this whole feature\'s authorization\nmodel rests on -- every repository method that lists/reads a customer\nfilters by it, and it\'s the field the IDOR test (see\ntests/domains/business/loan_book/test_ownership.py) exists to prove is\nactually enforced, not just present.\n"""\nfrom __future__ import annotations\n\nfrom sqlalchemy.dialects.postgresql import UUID\n\nfrom src.core.base_model import BaseModel\nfrom src.extensions import db\n\n\nclass Customer(BaseModel):\n    __tablename__ = "customers"\n    __table_args__ = (\n        db.Index("ix_customers_business_id", "business_id"),\n        db.Index("ix_customers_business_id_deleted", "business_id", "is_deleted"),\n        {"schema": "business"},\n    )\n\n    business_id = db.Column(\n        UUID(as_uuid=True), db.ForeignKey("auth.users.id"), nullable=False\n    )\n    name = db.Column(db.String(200), nullable=False)\n    # Optional by design (Doc 04 §3.4) -- many informal customers are\n    # known by name and face only.\n    phone = db.Column(db.String(20), nullable=True)\n    first_recorded_at = db.Column(db.DateTime(timezone=True), nullable=False)\n    last_transaction_at = db.Column(db.DateTime(timezone=True), nullable=True)\n    # is_deleted / deleted_at inherited from BaseModel -- customers are\n    # soft-deleted (Doc 06 §17), matching the frontend\'s Trash feature.\n    deletion_reason = db.Column(db.String(500), nullable=True)\n'
FILES['backend/src/domains/business/loan_book/models/loan_entry.py'] = '"""\nLoanEntry -- one credit sale. Matches the frontend\'s LoanEntry shape.\n\nbusiness_id is DENORMALIZED here (also present on Customer, which this\nrow belongs to via customer_id) -- deliberately, not accidentally. Every\nauthorization check on an entry needs to answer "does this belong to the\nrequesting business?" and doing that via a single indexed column beats\njoining through Customer on every single request. The two values must\nalways agree; see the service layer\'s create_entry(), the only place\nthat ever sets both at once.\n\nMoney is BIGINT cents, never NUMERIC/DECIMAL/FLOAT -- see\nshared/finance/README.md for the full reasoning. original_amount_cents\nis immutable once set; the CURRENT outstanding balance is never stored\n-- it\'s always derived from this row plus its Payments, exactly like the\nfrontend\'s balanceCalculator.ts already does. Storing a derived value\nrisks it silently drifting from the truth; deriving it every time makes\nthat drift structurally impossible.\n"""\nfrom __future__ import annotations\n\nfrom sqlalchemy.dialects.postgresql import UUID\n\nfrom src.core.base_model import BaseModel\nfrom src.extensions import db\n\n\nclass LoanEntry(BaseModel):\n    __tablename__ = "loan_entries"\n    __table_args__ = (\n        db.Index("ix_loan_entries_business_id", "business_id"),\n        db.Index("ix_loan_entries_business_id_deleted", "business_id", "is_deleted"),\n        db.Index("ix_loan_entries_customer_id", "customer_id"),\n        db.CheckConstraint("original_amount_cents > 0", name="ck_loan_entries_positive_amount"),\n        {"schema": "business"},\n    )\n\n    business_id = db.Column(\n        UUID(as_uuid=True), db.ForeignKey("auth.users.id"), nullable=False\n    )\n    customer_id = db.Column(\n        UUID(as_uuid=True), db.ForeignKey("business.customers.id"), nullable=False\n    )\n    original_amount_cents = db.Column(db.BigInteger, nullable=False)\n    sale_date = db.Column(db.DateTime(timezone=True), nullable=False)\n    description = db.Column(db.String(500), nullable=True)\n    is_settled = db.Column(db.Boolean, nullable=False, default=False)\n    settled_at = db.Column(db.DateTime(timezone=True), nullable=True)\n    # is_deleted / deleted_at inherited from BaseModel.\n    deletion_reason = db.Column(db.String(500), nullable=True)\n'
FILES['backend/src/domains/business/loan_book/models/payment.py'] = '"""\nPayment -- one repayment against a LoanEntry. Matches the frontend\'s\nPayment shape.\n\nDELIBERATELY NO business_id here, unlike Customer/LoanEntry: a payment\nhas no independent existence -- it only ever exists attached to one\nLoanEntry, and every route that touches a payment already has to load\nand authorize that parent entry first. Denormalizing business_id onto\nPayment too would be a second copy of the same fact with no query it\nactually speeds up, since a payment is never listed or searched\nindependently of its entry.\n\nDELIBERATELY NO is_deleted use here either, even though BaseModel\nprovides the columns structurally (for schema consistency across every\nmodel): the frontend\'s deletePayment() is a genuine hard delete, not a\nsoft one -- removing an accidentally-recorded payment is a correction,\nnot something that needs a 7-day recovery window the way removing a\nwhole entry does. The service layer enforces this distinction; the\ncolumns existing on the model is harmless, unused dead weight for this\none table specifically.\n"""\nfrom __future__ import annotations\n\nfrom sqlalchemy.dialects.postgresql import UUID\n\nfrom src.core.base_model import BaseModel\nfrom src.extensions import db\n\n\nclass Payment(BaseModel):\n    __tablename__ = "payments"\n    __table_args__ = (\n        db.Index("ix_payments_loan_entry_id", "loan_entry_id"),\n        db.CheckConstraint("amount_cents > 0", name="ck_payments_positive_amount"),\n        {"schema": "business"},\n    )\n\n    loan_entry_id = db.Column(\n        UUID(as_uuid=True), db.ForeignKey("business.loan_entries.id"), nullable=False\n    )\n    amount_cents = db.Column(db.BigInteger, nullable=False)\n    paid_at = db.Column(db.DateTime(timezone=True), nullable=False)\n    note = db.Column(db.String(500), nullable=True)\n'
FILES['backend/src/domains/business/loan_book/models/loan_history_event.py'] = '"""\nLoanHistoryEvent -- an append-only log of everything that happens in a\nbusiness\'s Loan Book: sales, payments, deletions, restores, receipt\ninteractions.\n\nWHY THIS ISN\'T shared.audit: the shape here is structurally identical\nto shared.audit\'s own design (append-only, one row per event, never\nmutated) -- but that\'s not merged into it, because shared.audit\'s real\ninternal structure (AuditEventName enum, the reserved-but-empty\nevent_types/business.py placeholder) has never been directly seen by\nwhoever wrote this. Guessing at how a new domain plugs into an existing\nsystem, without seeing its real shape, is exactly the mistake that cost\nreal back-and-forth earlier in this project (test_runner.py\'s\nJobExecutionOutcome fields). Building Loan Book\'s own small event log\nnow, matching shared.audit\'s PATTERN without touching its CODE, is the\nsame call the frontend already made for the same reason -- and it means\nthe eventual merge is a deliberate architecture decision made by someone\nwho can see both real systems at once, not an accidental one made by\nsomeone guessing at half of it.\n\nbusiness_id is present here too, same ownership-filtering discipline as\nevery other model in this feature.\n"""\nfrom __future__ import annotations\n\nimport enum\nimport uuid\n\nfrom sqlalchemy.dialects.postgresql import JSONB, UUID\n\nfrom src.core.base_model import utcnow\nfrom src.extensions import db\n\n\nclass LoanHistoryEventType(str, enum.Enum):\n    SALE_CREATED = "sale_created"\n    PAYMENT_RECORDED = "payment_recorded"\n    PAYMENT_REMOVED = "payment_removed"\n    ENTRY_DELETED = "entry_deleted"\n    ENTRY_RESTORED = "entry_restored"\n    CUSTOMER_CREATED = "customer_created"\n    CUSTOMER_DELETED = "customer_deleted"\n    CUSTOMER_RESTORED = "customer_restored"\n    RECEIPT_VIEWED = "receipt_viewed"\n    RECEIPT_SHARED = "receipt_shared"\n\n\n# The subset shown on the customer-facing Transaction History screen --\n# mirrors the frontend\'s TRANSACTION_EVENT_TYPES exactly (same reasoning:\n# a bank statement shows money movements, not "card deleted").\nTRANSACTION_EVENT_TYPES = frozenset({\n    LoanHistoryEventType.SALE_CREATED,\n    LoanHistoryEventType.PAYMENT_RECORDED,\n    LoanHistoryEventType.PAYMENT_REMOVED,\n})\n\n\nclass LoanHistoryEvent(db.Model):\n    __tablename__ = "loan_history_events"\n    __table_args__ = (\n        db.Index("ix_loan_history_business_id", "business_id"),\n        db.Index("ix_loan_history_business_id_occurred", "business_id", "occurred_at"),\n        {"schema": "business"},\n    )\n\n    id = db.Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)\n    business_id = db.Column(UUID(as_uuid=True), db.ForeignKey("auth.users.id"), nullable=False)\n    customer_id = db.Column(UUID(as_uuid=True), nullable=False)\n    loan_entry_id = db.Column(UUID(as_uuid=True), nullable=True)\n    event_type = db.Column(db.Enum(LoanHistoryEventType, name="loan_history_event_type"), nullable=False)\n    amount_cents = db.Column(db.BigInteger, nullable=True)\n    description = db.Column(db.String(500), nullable=True)\n    reason = db.Column(db.String(500), nullable=True)\n    event_metadata = db.Column("metadata", JSONB, nullable=False, default=dict)\n    occurred_at = db.Column(db.DateTime(timezone=True), nullable=False, default=utcnow)\n'
FILES['backend/src/domains/business/loan_book/repositories/customer_repository.py'] = '"""\nCustomer data access.\n\nEVERY read method here takes business_id and filters by it -- this is\nNOT optional or a convenience parameter. It\'s the actual mechanism that\nmakes cross-business data leakage structurally impossible rather than\nmerely policy: there is no method on this class that can return a\ncustomer without being told which business is asking.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import List, Optional\n\nfrom src.domains.business.loan_book.models.customer import Customer\nfrom src.extensions import db\n\n\nclass CustomerRepository:\n    @staticmethod\n    def create(customer: Customer) -> Customer:\n        db.session.add(customer)\n        db.session.flush()\n        return customer\n\n    @staticmethod\n    def get_by_id(customer_id: uuid.UUID, business_id: uuid.UUID) -> Optional[Customer]:\n        """Returns None if the customer doesn\'t exist, is deleted, OR\n        belongs to a different business -- all three cases look\n        identical to the caller on purpose. A 404 for \'not yours\' and a\n        404 for \'doesn\'t exist\' must be indistinguishable, or the\n        response itself leaks whether a given ID is real."""\n        return Customer.query.filter_by(\n            id=customer_id, business_id=business_id, is_deleted=False\n        ).first()\n\n    @staticmethod\n    def list_for_business(business_id: uuid.UUID) -> List[Customer]:\n        return Customer.query.filter_by(business_id=business_id, is_deleted=False).all()\n\n    @staticmethod\n    def list_deleted_for_business(business_id: uuid.UUID) -> List[Customer]:\n        return Customer.query.filter_by(business_id=business_id, is_deleted=True).all()\n\n    @staticmethod\n    def search(business_id: uuid.UUID, term: str) -> List[Customer]:\n        pattern = f"%{term}%"\n        return Customer.query.filter(\n            Customer.business_id == business_id,\n            Customer.is_deleted == False,  # noqa: E712\n            db.or_(Customer.name.ilike(pattern), Customer.phone.ilike(pattern)),\n        ).all()\n'
FILES['backend/src/domains/business/loan_book/repositories/loan_repository.py'] = '"""\nLoanEntry data access. Same ownership-filtering discipline as\nCustomerRepository -- see that file\'s docstring.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import List, Optional\n\nfrom src.domains.business.loan_book.models.loan_entry import LoanEntry\nfrom src.extensions import db\n\n\nclass LoanRepository:\n    @staticmethod\n    def create(entry: LoanEntry) -> LoanEntry:\n        db.session.add(entry)\n        db.session.flush()\n        return entry\n\n    @staticmethod\n    def get_by_id(entry_id: uuid.UUID, business_id: uuid.UUID) -> Optional[LoanEntry]:\n        return LoanEntry.query.filter_by(\n            id=entry_id, business_id=business_id, is_deleted=False\n        ).first()\n\n    @staticmethod\n    def list_for_business(business_id: uuid.UUID) -> List[LoanEntry]:\n        return LoanEntry.query.filter_by(business_id=business_id, is_deleted=False).all()\n\n    @staticmethod\n    def list_for_customer(customer_id: uuid.UUID, business_id: uuid.UUID) -> List[LoanEntry]:\n        """Still filtered by business_id even though customer_id alone\n        would usually be enough -- defence in depth: even if a caller\n        somehow obtained another business\'s customer_id, this can never\n        return that customer\'s entries without ALSO matching business_id."""\n        return LoanEntry.query.filter_by(\n            customer_id=customer_id, business_id=business_id, is_deleted=False\n        ).all()\n\n    @staticmethod\n    def list_deleted_for_business(business_id: uuid.UUID) -> List[LoanEntry]:\n        return LoanEntry.query.filter_by(business_id=business_id, is_deleted=True).all()\n\n    @staticmethod\n    def list_for_customer_including_deleted(customer_id: uuid.UUID, business_id: uuid.UUID) -> List[LoanEntry]:\n        """For trash-summary purposes -- mirrors the frontend\n        repository\'s listEntriesForCustomerIncludingDeleted()."""\n        return LoanEntry.query.filter_by(customer_id=customer_id, business_id=business_id).all()\n'
FILES['backend/src/domains/business/loan_book/repositories/payment_repository.py'] = '"""\nPayment data access.\n\nNO business_id filter here -- see the model\'s own docstring for why.\nEvery method takes the ALREADY-AUTHORIZED loan_entry_id as its scoping\nkey; the service layer is responsible for confirming that entry belongs\nto the requesting business BEFORE ever calling into this repository.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import List\n\nfrom src.domains.business.loan_book.models.payment import Payment\nfrom src.extensions import db\n\n\nclass PaymentRepository:\n    @staticmethod\n    def create(payment: Payment) -> Payment:\n        db.session.add(payment)\n        db.session.flush()\n        return payment\n\n    @staticmethod\n    def list_for_entry(loan_entry_id: uuid.UUID) -> List[Payment]:\n        return Payment.query.filter_by(loan_entry_id=loan_entry_id).order_by(Payment.paid_at).all()\n\n    @staticmethod\n    def list_for_entries(loan_entry_ids: List[uuid.UUID]) -> List[Payment]:\n        if not loan_entry_ids:\n            return []\n        return Payment.query.filter(Payment.loan_entry_id.in_(loan_entry_ids)).all()\n\n    @staticmethod\n    def delete(payment: Payment) -> None:\n        """Genuine hard delete -- see Payment model\'s docstring for why\n        this differs from Customer/LoanEntry\'s soft-delete."""\n        db.session.delete(payment)\n        db.session.flush()\n'
FILES['backend/src/domains/business/loan_book/repositories/history_repository.py'] = '"""History event data access -- append-only: create and list, never\nupdate or delete, matching the model\'s own design."""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import List\n\nfrom src.domains.business.loan_book.models.loan_history_event import LoanHistoryEvent\nfrom src.extensions import db\n\n\nclass HistoryRepository:\n    @staticmethod\n    def append(event: LoanHistoryEvent) -> LoanHistoryEvent:\n        db.session.add(event)\n        db.session.flush()\n        return event\n\n    @staticmethod\n    def list_for_business(business_id: uuid.UUID) -> List[LoanHistoryEvent]:\n        return (\n            LoanHistoryEvent.query.filter_by(business_id=business_id)\n            .order_by(LoanHistoryEvent.occurred_at.desc())\n            .all()\n        )\n'
FILES['backend/src/domains/business/loan_book/services/errors.py'] = '"""\nLoan Book service-layer exceptions.\n\nLoanBookNotFoundError is used for BOTH "genuinely doesn\'t exist" and\n"exists but belongs to a different business" -- deliberately the same\nexception, carrying no information that would let a caller distinguish\nthe two. The API layer turns this into a plain 404 either way. This is\nthe actual authorization mechanism, not a courtesy: an attacker probing\nIDs must never be able to tell "wrong ID" from "someone else\'s real ID"\napart from the response.\n"""\nfrom __future__ import annotations\n\n\nclass LoanBookError(Exception):\n    """Base for every Loan Book service error."""\n\n\nclass LoanBookNotFoundError(LoanBookError):\n    """Customer/entry either doesn\'t exist, is deleted, or doesn\'t\n    belong to the requesting business -- see module docstring."""\n\n\nclass LoanBookValidationError(LoanBookError):\n    def __init__(self, message: str, field: str | None = None):\n        super().__init__(message)\n        self.message = message\n        self.field = field\n'
FILES['backend/src/domains/business/loan_book/services/loan_book_service.py'] = '"""\nLoan Book business operations.\n\nTHE AUTHORIZATION PATTERN, applied consistently everywhere in this\nfile: every method that touches an existing customer or entry takes\nbusiness_id as a REQUIRED parameter and calls the repository\'s\nget_by_id(id, business_id) -- which returns None for "doesn\'t exist" and\n"exists but isn\'t yours" identically (see repositories\' docstrings).\nThis service turns that None into LoanBookNotFoundError uniformly. There\nis no code path anywhere in this file that loads a row by ID alone and\nchecks ownership afterward -- ownership is baked into the fetch itself,\nwhich is what makes it structurally hard to accidentally bypass by\nforgetting a check, the classic shape of a real IDOR bug.\n\nMONEY: every amount is a shared.finance.Money instance from the moment\nit enters this file to the moment it leaves. The outstanding balance on\nan entry is NEVER stored -- it\'s derived fresh from the entry\'s original\namount minus the sum of its real payments, every time, using\nshared.finance.subtract()/total(). This exactly mirrors the frontend\'s\nbalanceCalculator.ts, so a shop owner\'s balance can never silently drift\nbetween what the app shows and what the database would compute if asked\ndirectly.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom typing import List, Optional\n\nfrom src.domains.business.loan_book.models.customer import Customer\nfrom src.domains.business.loan_book.models.loan_entry import LoanEntry\nfrom src.domains.business.loan_book.models.loan_history_event import LoanHistoryEvent, LoanHistoryEventType\nfrom src.domains.business.loan_book.models.payment import Payment\nfrom src.domains.business.loan_book.repositories.customer_repository import CustomerRepository\nfrom src.domains.business.loan_book.repositories.history_repository import HistoryRepository\nfrom src.domains.business.loan_book.repositories.loan_repository import LoanRepository\nfrom src.domains.business.loan_book.repositories.payment_repository import PaymentRepository\nfrom src.domains.business.loan_book.services.errors import LoanBookNotFoundError, LoanBookValidationError\nfrom src.extensions import db\nfrom src.shared.finance import Money, subtract, total, validate_payment, validate_positive\n\n\ndef _now() -> datetime:\n    return datetime.now(timezone.utc)\n\n\ndef _record_history(\n    business_id: uuid.UUID,\n    customer_id: uuid.UUID,\n    event_type: LoanHistoryEventType,\n    *,\n    loan_entry_id: Optional[uuid.UUID] = None,\n    amount: Optional[Money] = None,\n    description: Optional[str] = None,\n    reason: Optional[str] = None,\n) -> None:\n    """\n    NEVER THROWS -- same reasoning already established for the Auth\n    audit system (shared/audit.py\'s publish()): recording history must\n    never break the action being recorded. A lost history row is\n    survivable; a credit sale failing to save because ITS OWN history\n    entry failed to write would be a much worse outcome.\n    """\n    try:\n        HistoryRepository.append(LoanHistoryEvent(\n            id=uuid.uuid4(),\n            business_id=business_id,\n            customer_id=customer_id,\n            loan_entry_id=loan_entry_id,\n            event_type=event_type,\n            amount_cents=amount.minor_units if amount is not None else None,\n            description=description,\n            reason=reason,\n        ))\n    except Exception:  # noqa: BLE001\n        pass\n\n\n@dataclass\nclass LoanEntryView:\n    """The API/service-layer answer to \'how much is still owed on this\n    entry\' -- outstanding is ALWAYS derived here, never read from a\n    stored column, matching balanceCalculator.ts exactly."""\n\n    entry: LoanEntry\n    payments: List[Payment]\n    outstanding: Money\n    amount_paid: Money\n\n\ndef _derive_view(entry: LoanEntry, payments: List[Payment]) -> LoanEntryView:\n    original = Money(entry.original_amount_cents)\n    paid = total([Money(p.amount_cents) for p in payments], currency=original.currency)\n    outstanding = subtract(original, paid)\n    # A payment can never legitimately exceed the debt (enforced at\n    # record_payment time below) -- clamping here is a second, cheap\n    # guard against outstanding ever reading as negative regardless.\n    if outstanding.is_negative:\n        outstanding = Money.zero(original.currency)\n    return LoanEntryView(entry=entry, payments=payments, outstanding=outstanding, amount_paid=paid)\n\n\nclass LoanBookService:\n    # --- Customers ------------------------------------------------------\n\n    @staticmethod\n    def create_customer(\n        business_id: uuid.UUID,\n        name: str,\n        phone: Optional[str] = None,\n        customer_id: Optional[uuid.UUID] = None,\n    ) -> Customer:\n        """customer_id accepts an optional CLIENT-SUPPLIED id -- the\n        frontend already generates its own UUIDs offline-first\n        (generateId() in loanBookApi.ts); accepting that same id here,\n        rather than always generating a new server-side one, is what\n        lets a record created offline reconcile to the exact same row\n        once synced, instead of creating a duplicate."""\n        if not name or not name.strip():\n            raise LoanBookValidationError("Customer name is required.", field="name")\n\n        now = _now()\n        customer = Customer(\n            id=customer_id or uuid.uuid4(),\n            business_id=business_id,\n            name=name.strip(),\n            phone=phone.strip() if phone else None,\n            first_recorded_at=now,\n            last_transaction_at=now,\n        )\n        CustomerRepository.create(customer)\n        _record_history(business_id, customer.id, LoanHistoryEventType.CUSTOMER_CREATED)\n        db.session.commit()\n        return customer\n\n    @staticmethod\n    def get_customer(business_id: uuid.UUID, customer_id: uuid.UUID) -> Customer:\n        customer = CustomerRepository.get_by_id(customer_id, business_id)\n        if customer is None:\n            raise LoanBookNotFoundError("Customer not found.")\n        return customer\n\n    @staticmethod\n    def list_customers(business_id: uuid.UUID) -> List[Customer]:\n        return CustomerRepository.list_for_business(business_id)\n\n    # --- Loan entries -----------------------------------------------------\n\n    @staticmethod\n    def create_entry(\n        business_id: uuid.UUID,\n        customer_id: uuid.UUID,\n        amount: Money,\n        description: Optional[str] = None,\n        sale_date: Optional[datetime] = None,\n        entry_id: Optional[uuid.UUID] = None,\n    ) -> LoanEntry:\n        # Ownership check happens by construction: get_customer() can\n        # only ever return a customer that belongs to business_id, so a\n        # caller cannot create an entry against someone else\'s customer\n        # even by supplying a real customer_id they don\'t own.\n        customer = LoanBookService.get_customer(business_id, customer_id)\n\n        result = validate_positive(amount)\n        if not result.is_valid:\n            raise LoanBookValidationError(result.message, field="amount")\n\n        now = _now()\n        entry = LoanEntry(\n            id=entry_id or uuid.uuid4(),\n            business_id=business_id,  # copied from the AUTHORIZED business_id, never trusted from elsewhere\n            customer_id=customer.id,\n            original_amount_cents=amount.minor_units,\n            sale_date=sale_date or now,\n            description=description.strip() if description else None,\n            is_settled=False,\n        )\n        LoanRepository.create(entry)\n        _record_history(\n            business_id, customer.id, LoanHistoryEventType.SALE_CREATED,\n            loan_entry_id=entry.id, amount=amount, description=entry.description,\n        )\n\n        customer.last_transaction_at = now\n        db.session.commit()\n        return entry\n\n    @staticmethod\n    def get_entry(business_id: uuid.UUID, entry_id: uuid.UUID) -> LoanEntryView:\n        entry = LoanRepository.get_by_id(entry_id, business_id)\n        if entry is None:\n            raise LoanBookNotFoundError("Entry not found.")\n        payments = PaymentRepository.list_for_entry(entry.id)\n        return _derive_view(entry, payments)\n\n    @staticmethod\n    def list_entries(business_id: uuid.UUID) -> List[LoanEntryView]:\n        entries = LoanRepository.list_for_business(business_id)\n        if not entries:\n            return []\n        payments = PaymentRepository.list_for_entries([e.id for e in entries])\n        by_entry: dict[uuid.UUID, List[Payment]] = {}\n        for p in payments:\n            by_entry.setdefault(p.loan_entry_id, []).append(p)\n        return [_derive_view(e, by_entry.get(e.id, [])) for e in entries]\n\n    @staticmethod\n    def delete_entry(business_id: uuid.UUID, entry_id: uuid.UUID, reason: Optional[str] = None) -> None:\n        entry = LoanRepository.get_by_id(entry_id, business_id)\n        if entry is None:\n            raise LoanBookNotFoundError("Entry not found.")\n        entry.is_deleted = True\n        entry.deleted_at = _now()\n        entry.deletion_reason = reason\n        _record_history(\n            business_id, entry.customer_id, LoanHistoryEventType.ENTRY_DELETED,\n            loan_entry_id=entry.id, reason=reason,\n        )\n        db.session.commit()\n\n    # --- Payments -----------------------------------------------------\n\n    @staticmethod\n    def record_payment(\n        business_id: uuid.UUID,\n        entry_id: uuid.UUID,\n        amount: Money,\n        note: Optional[str] = None,\n        paid_at: Optional[datetime] = None,\n        payment_id: Optional[uuid.UUID] = None,\n    ) -> LoanEntryView:\n        # Same ownership-by-construction pattern as create_entry(): this\n        # can only ever load an entry the caller\'s own business owns.\n        view = LoanBookService.get_entry(business_id, entry_id)\n\n        result = validate_payment(amount, view.outstanding)\n        if not result.is_valid:\n            raise LoanBookValidationError(result.message, field="amount")\n\n        now = _now()\n        payment = Payment(\n            id=payment_id or uuid.uuid4(),\n            loan_entry_id=view.entry.id,\n            amount_cents=amount.minor_units,\n            paid_at=paid_at or now,\n            note=note.strip() if note else None,\n        )\n        PaymentRepository.create(payment)\n        _record_history(\n            business_id, view.entry.customer_id, LoanHistoryEventType.PAYMENT_RECORDED,\n            loan_entry_id=view.entry.id, amount=amount,\n        )\n\n        new_outstanding = subtract(view.outstanding, amount)\n        if new_outstanding.is_zero:\n            view.entry.is_settled = True\n            view.entry.settled_at = now\n\n        db.session.commit()\n        return LoanBookService.get_entry(business_id, entry_id)\n\n    @staticmethod\n    def delete_payment(business_id: uuid.UUID, entry_id: uuid.UUID, payment_id: uuid.UUID) -> LoanEntryView:\n        """Ownership enforced via the SAME get_entry() call every other\n        payment-touching method uses -- a payment can only ever be\n        deleted through an entry the caller\'s own business owns."""\n        view = LoanBookService.get_entry(business_id, entry_id)\n        target = next((p for p in view.payments if p.id == payment_id), None)\n        if target is None:\n            raise LoanBookNotFoundError("Payment not found.")\n\n        PaymentRepository.delete(target)\n        _record_history(\n            business_id, view.entry.customer_id, LoanHistoryEventType.PAYMENT_REMOVED,\n            loan_entry_id=view.entry.id, amount=Money(target.amount_cents),\n        )\n\n        # Re-derive settlement status -- removing a payment can un-settle\n        # an entry that was previously fully paid.\n        remaining_payments = [p for p in view.payments if p.id != payment_id]\n        remaining_view = _derive_view(view.entry, remaining_payments)\n        if not remaining_view.outstanding.is_zero:\n            view.entry.is_settled = False\n            view.entry.settled_at = None\n\n        db.session.commit()\n        return LoanBookService.get_entry(business_id, entry_id)\n\n    # --- Restore / soft-delete lifecycle -------------------------------\n\n    @staticmethod\n    def restore_entry(business_id: uuid.UUID, entry_id: uuid.UUID) -> LoanEntry:\n        """Restores an entry that was deleted independently (not as\n        part of a customer cascade) -- or one that WAS cascade-deleted\n        but whose customer has since also been restored. Only entries\n        still owned by business_id can ever be found here; a deleted\n        row belonging to another business is exactly as invisible as an\n        active one."""\n        entry = LoanEntry.query.filter_by(\n            id=entry_id, business_id=business_id, is_deleted=True\n        ).first()\n        if entry is None:\n            raise LoanBookNotFoundError("Entry not found in trash.")\n        entry.is_deleted = False\n        entry.deleted_at = None\n        entry.deletion_reason = None\n        _record_history(business_id, entry.customer_id, LoanHistoryEventType.ENTRY_RESTORED, loan_entry_id=entry.id)\n        db.session.commit()\n        return entry\n\n    @staticmethod\n    def delete_customer(business_id: uuid.UUID, customer_id: uuid.UUID, reason: Optional[str] = None) -> None:\n        """\n        Soft-deletes the customer AND cascades to their currently-open\n        entries -- mirrors the frontend\'s MockDataRepository.softDeleteCustomer()\n        exactly, including the cascade-marker mechanism: entries swept\n        in by this cascade get the SAME deleted_at timestamp as the\n        customer, which is what lets restore_customer() below know\n        precisely which entries to bring back (and which to leave\n        alone, if they were independently deleted at a different time).\n        """\n        customer = CustomerRepository.get_by_id(customer_id, business_id)\n        if customer is None:\n            raise LoanBookNotFoundError("Customer not found.")\n\n        now = _now()\n        customer.is_deleted = True\n        customer.deleted_at = now\n        customer.deletion_reason = reason\n\n        open_entries = LoanRepository.list_for_customer(customer_id, business_id)\n        for entry in open_entries:\n            entry.is_deleted = True\n            entry.deleted_at = now  # shared cascade marker -- see docstring\n            entry.deletion_reason = f"Customer removed: {reason}" if reason else "Customer removed"\n\n        _record_history(business_id, customer.id, LoanHistoryEventType.CUSTOMER_DELETED, reason=reason)\n        db.session.commit()\n\n    @staticmethod\n    def restore_customer(business_id: uuid.UUID, customer_id: uuid.UUID) -> Customer:\n        customer = Customer.query.filter_by(\n            id=customer_id, business_id=business_id, is_deleted=True\n        ).first()\n        if customer is None:\n            raise LoanBookNotFoundError("Customer not found in trash.")\n\n        cascade_marker = customer.deleted_at\n        customer.is_deleted = False\n        customer.deleted_at = None\n        customer.deletion_reason = None\n\n        # Only restore entries stamped with the SAME deletion timestamp\n        # -- i.e. ones that went into trash as PART OF THIS CASCADE, not\n        # an entry independently deleted at some other time.\n        cascaded_entries = LoanEntry.query.filter_by(\n            customer_id=customer_id, business_id=business_id, is_deleted=True, deleted_at=cascade_marker\n        ).all()\n        for entry in cascaded_entries:\n            entry.is_deleted = False\n            entry.deleted_at = None\n            entry.deletion_reason = None\n\n        _record_history(business_id, customer.id, LoanHistoryEventType.CUSTOMER_RESTORED)\n        db.session.commit()\n        return customer\n\n    @staticmethod\n    def get_trash(business_id: uuid.UUID) -> dict:\n        """Mirrors the frontend\'s getTrash(): deleted customers get\n        their own summary row; deleted entries only appear separately\n        when their OWN customer is currently active (not itself\n        deleted) -- see loan_repository/customer_repository for the\n        exact filtering this depends on."""\n        deleted_customers = CustomerRepository.list_deleted_for_business(business_id)\n        deleted_customer_ids = {c.id for c in deleted_customers}\n\n        all_deleted_entries = LoanRepository.list_deleted_for_business(business_id)\n        independent_entries = [\n            e for e in all_deleted_entries if e.customer_id not in deleted_customer_ids\n        ]\n\n        customer_summaries = []\n        for customer in deleted_customers:\n            all_entries = LoanRepository.list_for_customer_including_deleted(customer.id, business_id)\n            payments = PaymentRepository.list_for_entries([e.id for e in all_entries])\n            by_entry: dict[uuid.UUID, List[Payment]] = {}\n            for p in payments:\n                by_entry.setdefault(p.loan_entry_id, []).append(p)\n            views = [_derive_view(e, by_entry.get(e.id, [])) for e in all_entries]\n            customer_summaries.append({\n                "customer": customer,\n                "open_entry_count": sum(1 for v in views if v.outstanding.is_positive),\n                "total_entry_count": len(views),\n                "total_outstanding": total([v.outstanding for v in views]) if views else Money.zero(),\n            })\n\n        return {"customers": customer_summaries, "entries": independent_entries}\n\n    # --- Customer aggregate view (customer-first list) ------------------\n\n    @staticmethod\n    def get_customer_view(business_id: uuid.UUID, customer_id: uuid.UUID) -> dict:\n        customer = LoanBookService.get_customer(business_id, customer_id)\n        entries = LoanRepository.list_for_customer(customer_id, business_id)\n        payments = PaymentRepository.list_for_entries([e.id for e in entries])\n        by_entry: dict[uuid.UUID, List[Payment]] = {}\n        for p in payments:\n            by_entry.setdefault(p.loan_entry_id, []).append(p)\n        views = [_derive_view(e, by_entry.get(e.id, [])) for e in entries]\n        outstanding_total = total([v.outstanding for v in views]) if views else Money.zero()\n        return {\n            "customer": customer,\n            "entries": views,\n            "total_outstanding": outstanding_total,\n            "open_entry_count": sum(1 for v in views if v.outstanding.is_positive),\n            "has_overdue": False,  # overdue-threshold logic lives with aging, not this view\n        }\n\n    @staticmethod\n    def list_customer_views(business_id: uuid.UUID) -> List[dict]:\n        customers = CustomerRepository.list_for_business(business_id)\n        return [LoanBookService.get_customer_view(business_id, c.id) for c in customers]\n\n    # --- Transaction history (bank-statement view) ---------------------\n\n    @staticmethod\n    def get_transaction_history(business_id: uuid.UUID) -> List[LoanHistoryEvent]:\n        """Filtered to the same subset the frontend\'s Transaction\n        History screen shows -- sales, payments, payment removals.\n        Deletions/restores/receipt views still get recorded (for the\n        eventual full audit trail) but don\'t belong on a screen whose\n        entire premise is \'what money moved\'."""\n        from src.domains.business.loan_book.models.loan_history_event import TRANSACTION_EVENT_TYPES\n\n        all_events = HistoryRepository.list_for_business(business_id)\n        return [e for e in all_events if e.event_type in TRANSACTION_EVENT_TYPES]\n\n    @staticmethod\n    def get_full_history(business_id: uuid.UUID) -> List[LoanHistoryEvent]:\n        """Every event, unfiltered -- for a future full-audit view."""\n        return HistoryRepository.list_for_business(business_id)\n'
FILES['backend/src/domains/business/loan_book/schemas/loan_book_schemas.py'] = '"""\nLoan Book request/response schemas.\n\nField names use data_key to match the mobile app\'s camelCase wire\nformat (frontend Loan Book\'s types.ts) exactly -- same convention\nalready established in auth_schemas.py.\n\nAmount fields use `amount_cents`/`original_amount_cents` naming, never\na bare `amount` -- so nobody reading a request or response has to guess\nwhether a number means cents or rands. Same reasoning already applied\nthroughout the Finance Engine\'s own API surface.\n\nNOTE: outgoing Money values are NOT serialized by a Schema here -- the\nroute layer calls shared.finance.format_for_json() directly, which\nalready returns the exact {minor_units, currency, formatted} shape\nevery response uses. These schemas only validate INCOMING requests.\n"""\nfrom __future__ import annotations\n\nfrom marshmallow import Schema, fields, validate\n\n\nclass CreateCustomerSchema(Schema):\n    name = fields.String(required=True, validate=validate.Length(min=1, max=200))\n    phone = fields.String(required=False, allow_none=True, validate=validate.Length(max=20))\n    # Optional client-supplied id -- see LoanBookService.create_customer()\n    # docstring for why this matters for offline-first sync.\n    id = fields.UUID(required=False, allow_none=True)\n\n\nclass CreateLoanEntrySchema(Schema):\n    customer_id = fields.UUID(required=True, data_key="customerId")\n    amount_cents = fields.Integer(required=True, data_key="amountCents", validate=validate.Range(min=1))\n    description = fields.String(required=False, allow_none=True, validate=validate.Length(max=500))\n    id = fields.UUID(required=False, allow_none=True)\n\n\nclass RecordPaymentSchema(Schema):\n    amount_cents = fields.Integer(required=True, data_key="amountCents", validate=validate.Range(min=1))\n    note = fields.String(required=False, allow_none=True, validate=validate.Length(max=500))\n    id = fields.UUID(required=False, allow_none=True)\n\n\nclass DeleteReasonSchema(Schema):\n    reason = fields.String(required=False, allow_none=True, validate=validate.Length(max=500))\n'
FILES['backend/src/domains/business/loan_book/api/loan_book_routes.py'] = '"""\nLoan Book HTTP routes.\n\nAUTH DECORATOR ASSUMPTION, flagged rather than guessed silently: uses\n`fully_authenticated`, imported from `src.domains.auth.decorators`. This\nname is confirmed to be REAL (referenced by name in test_auth.py\'s own\ndocstring: "@fully_authenticated re-checks the database, not the\ntoken"), but its exact IMPORT PATH has not been directly seen -- verify\nthis against the real file and correct the import if it lives elsewhere\n(e.g. src.domains.auth.utils.decorators). Everything downstream of the\nimport is independent of exactly where it lives.\n\nbusiness_id is taken from get_jwt_identity() -- the authenticated\ncaller\'s own user id -- NEVER from anything in the request body or URL.\nThis is not a style preference: it\'s the actual mechanism the whole\nownership model (see services/loan_book_service.py, and\ntests/domains/business/loan_book/test_ownership.py) depends on. A route\nthat read business_id from a request parameter instead would make every\nownership check downstream pointless, since an attacker could simply\nclaim to be whichever business they wanted.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom flask import Blueprint, jsonify, request\nfrom flask_jwt_extended import get_jwt_identity\nfrom marshmallow import ValidationError as MarshmallowValidationError\n\nfrom src.domains.auth.decorators import fully_authenticated  # VERIFY: exact import path\nfrom src.domains.business.loan_book.schemas.loan_book_schemas import (\n    CreateCustomerSchema,\n    CreateLoanEntrySchema,\n    DeleteReasonSchema,\n    RecordPaymentSchema,\n)\nfrom src.domains.business.loan_book.services.errors import LoanBookNotFoundError, LoanBookValidationError\nfrom src.domains.business.loan_book.services.loan_book_service import LoanBookService\nfrom src.shared.finance import Money, format_for_json\n\nloan_book_bp = Blueprint("loan_book", __name__)\n\n\ndef _business_id() -> uuid.UUID:\n    return uuid.UUID(get_jwt_identity())\n\n\ndef _entry_view_to_dict(view) -> dict:\n    return {\n        "id": str(view.entry.id),\n        "customerId": str(view.entry.customer_id),\n        "description": view.entry.description,\n        "saleDate": view.entry.sale_date.isoformat(),\n        "isSettled": view.entry.is_settled,\n        "settledAt": view.entry.settled_at.isoformat() if view.entry.settled_at else None,\n        "originalAmount": format_for_json(Money(view.entry.original_amount_cents)),\n        "amountPaid": format_for_json(view.amount_paid),\n        "outstandingAmount": format_for_json(view.outstanding),\n        "payments": [_payment_to_dict(p) for p in view.payments],\n    }\n\n\ndef _payment_to_dict(payment) -> dict:\n    return {\n        "id": str(payment.id),\n        "amount": format_for_json(Money(payment.amount_cents)),\n        "paidAt": payment.paid_at.isoformat(),\n        "note": payment.note,\n    }\n\n\ndef _customer_to_dict(customer) -> dict:\n    return {\n        "id": str(customer.id),\n        "name": customer.name,\n        "phone": customer.phone,\n        "firstRecordedAt": customer.first_recorded_at.isoformat(),\n        "lastTransactionAt": customer.last_transaction_at.isoformat() if customer.last_transaction_at else None,\n    }\n\n\ndef _customer_view_to_dict(view: dict) -> dict:\n    return {\n        "customer": _customer_to_dict(view["customer"]),\n        "entries": [_entry_view_to_dict(v) for v in view["entries"]],\n        "totalOutstanding": format_for_json(view["total_outstanding"]),\n        "openEntryCount": view["open_entry_count"],\n    }\n\n\n# --- Customers ----------------------------------------------------------\n\n@loan_book_bp.route("/api/v1/loan-book/customers", methods=["POST"])\n@fully_authenticated\ndef create_customer():\n    try:\n        data = CreateCustomerSchema().load(request.get_json(silent=True) or {})\n    except MarshmallowValidationError as exc:\n        return jsonify(success=False, errors=exc.messages), 422\n\n    customer = LoanBookService.create_customer(\n        _business_id(), data["name"], data.get("phone"), customer_id=data.get("id")\n    )\n    return jsonify(success=True, data=_customer_to_dict(customer)), 201\n\n\n@loan_book_bp.route("/api/v1/loan-book/customers", methods=["GET"])\n@fully_authenticated\ndef list_customers():\n    views = LoanBookService.list_customer_views(_business_id())\n    return jsonify(success=True, data=[_customer_view_to_dict(v) for v in views])\n\n\n@loan_book_bp.route("/api/v1/loan-book/customers/<uuid:customer_id>", methods=["GET"])\n@fully_authenticated\ndef get_customer(customer_id: uuid.UUID):\n    try:\n        view = LoanBookService.get_customer_view(_business_id(), customer_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Customer not found."), 404\n    return jsonify(success=True, data=_customer_view_to_dict(view))\n\n\n@loan_book_bp.route("/api/v1/loan-book/customers/<uuid:customer_id>", methods=["DELETE"])\n@fully_authenticated\ndef delete_customer(customer_id: uuid.UUID):\n    data = DeleteReasonSchema().load(request.get_json(silent=True) or {})\n    try:\n        LoanBookService.delete_customer(_business_id(), customer_id, reason=data.get("reason"))\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Customer not found."), 404\n    return jsonify(success=True), 200\n\n\n@loan_book_bp.route("/api/v1/loan-book/customers/<uuid:customer_id>/restore", methods=["POST"])\n@fully_authenticated\ndef restore_customer(customer_id: uuid.UUID):\n    try:\n        customer = LoanBookService.restore_customer(_business_id(), customer_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Customer not found in trash."), 404\n    return jsonify(success=True, data=_customer_to_dict(customer))\n\n\n# --- Loan entries ---------------------------------------------------------\n\n@loan_book_bp.route("/api/v1/loan-book/entries", methods=["POST"])\n@fully_authenticated\ndef create_entry():\n    try:\n        data = CreateLoanEntrySchema().load(request.get_json(silent=True) or {})\n    except MarshmallowValidationError as exc:\n        return jsonify(success=False, errors=exc.messages), 422\n\n    try:\n        entry = LoanBookService.create_entry(\n            _business_id(),\n            data["customer_id"],\n            Money(data["amount_cents"]),\n            description=data.get("description"),\n            entry_id=data.get("id"),\n        )\n    except LoanBookNotFoundError:\n        # Same response as "customer doesn\'t exist" -- see\n        # LoanBookNotFoundError\'s docstring for why this ambiguity is\n        # deliberate, not an oversight.\n        return jsonify(success=False, message="Customer not found."), 404\n    except LoanBookValidationError as exc:\n        return jsonify(success=False, message=exc.message, field=exc.field), 422\n\n    view = LoanBookService.get_entry(_business_id(), entry.id)\n    return jsonify(success=True, data=_entry_view_to_dict(view)), 201\n\n\n@loan_book_bp.route("/api/v1/loan-book/entries", methods=["GET"])\n@fully_authenticated\ndef list_entries():\n    views = LoanBookService.list_entries(_business_id())\n    return jsonify(success=True, data=[_entry_view_to_dict(v) for v in views])\n\n\n@loan_book_bp.route("/api/v1/loan-book/entries/<uuid:entry_id>", methods=["GET"])\n@fully_authenticated\ndef get_entry(entry_id: uuid.UUID):\n    try:\n        view = LoanBookService.get_entry(_business_id(), entry_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry not found."), 404\n    return jsonify(success=True, data=_entry_view_to_dict(view))\n\n\n@loan_book_bp.route("/api/v1/loan-book/entries/<uuid:entry_id>", methods=["DELETE"])\n@fully_authenticated\ndef delete_entry(entry_id: uuid.UUID):\n    data = DeleteReasonSchema().load(request.get_json(silent=True) or {})\n    try:\n        LoanBookService.delete_entry(_business_id(), entry_id, reason=data.get("reason"))\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry not found."), 404\n    return jsonify(success=True), 200\n\n\n@loan_book_bp.route("/api/v1/loan-book/entries/<uuid:entry_id>/restore", methods=["POST"])\n@fully_authenticated\ndef restore_entry(entry_id: uuid.UUID):\n    try:\n        entry = LoanBookService.restore_entry(_business_id(), entry_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry not found in trash."), 404\n    view = LoanBookService.get_entry(_business_id(), entry.id)\n    return jsonify(success=True, data=_entry_view_to_dict(view))\n\n\n# --- Payments -------------------------------------------------------------\n\n@loan_book_bp.route("/api/v1/loan-book/entries/<uuid:entry_id>/payments", methods=["POST"])\n@fully_authenticated\ndef record_payment(entry_id: uuid.UUID):\n    try:\n        data = RecordPaymentSchema().load(request.get_json(silent=True) or {})\n    except MarshmallowValidationError as exc:\n        return jsonify(success=False, errors=exc.messages), 422\n\n    try:\n        view = LoanBookService.record_payment(\n            _business_id(),\n            entry_id,\n            Money(data["amount_cents"]),\n            note=data.get("note"),\n            payment_id=data.get("id"),\n        )\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry not found."), 404\n    except LoanBookValidationError as exc:\n        return jsonify(success=False, message=exc.message, field=exc.field), 422\n\n    return jsonify(success=True, data=_entry_view_to_dict(view)), 201\n\n\n@loan_book_bp.route(\n    "/api/v1/loan-book/entries/<uuid:entry_id>/payments/<uuid:payment_id>", methods=["DELETE"]\n)\n@fully_authenticated\ndef delete_payment(entry_id: uuid.UUID, payment_id: uuid.UUID):\n    try:\n        view = LoanBookService.delete_payment(_business_id(), entry_id, payment_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry or payment not found."), 404\n    return jsonify(success=True, data=_entry_view_to_dict(view))\n\n\n# --- Transaction history ---------------------------------------------\n\ndef _history_event_to_dict(event) -> dict:\n    return {\n        "id": str(event.id),\n        "customerId": str(event.customer_id),\n        "loanEntryId": str(event.loan_entry_id) if event.loan_entry_id else None,\n        "eventType": event.event_type.value,\n        "amount": format_for_json(Money(event.amount_cents)) if event.amount_cents is not None else None,\n        "description": event.description,\n        "reason": event.reason,\n        "occurredAt": event.occurred_at.isoformat(),\n    }\n\n\n@loan_book_bp.route("/api/v1/loan-book/history", methods=["GET"])\n@fully_authenticated\ndef get_transaction_history():\n    events = LoanBookService.get_transaction_history(_business_id())\n    return jsonify(success=True, data=[_history_event_to_dict(e) for e in events])\n\n\n# --- Receipt ------------------------------------------------------------\n\n@loan_book_bp.route("/api/v1/loan-book/entries/<uuid:entry_id>/receipt", methods=["GET"])\n@fully_authenticated\ndef get_receipt(entry_id: uuid.UUID):\n    from src.domains.business.loan_book.utils.receipt_builder import build_receipt_data\n\n    try:\n        view = LoanBookService.get_entry(_business_id(), entry_id)\n        customer = LoanBookService.get_customer(_business_id(), view.entry.customer_id)\n    except LoanBookNotFoundError:\n        return jsonify(success=False, message="Entry not found."), 404\n\n    receipt = build_receipt_data(view, customer.name)\n    return jsonify(\n        success=True,\n        data={\n            "referenceCode": receipt.reference_code,\n            "customerName": receipt.customer_name,\n            "fromLabel": receipt.from_label,\n            "saleDateLabel": receipt.sale_date_label,\n            "description": receipt.description,\n            "originalAmountLabel": receipt.original_amount_label,\n            "amountPaidLabel": receipt.amount_paid_label,\n            "outstandingAmountLabel": receipt.outstanding_amount_label,\n            "isSettled": receipt.is_settled,\n            "isPartlyPaid": receipt.is_partly_paid,\n        },\n    )\n\n\n# --- Trash ------------------------------------------------------------\n\n@loan_book_bp.route("/api/v1/loan-book/trash", methods=["GET"])\n@fully_authenticated\ndef get_trash():\n    trash = LoanBookService.get_trash(_business_id())\n    return jsonify(\n        success=True,\n        data={\n            "customers": [\n                {\n                    **_customer_to_dict(c["customer"]),\n                    "openEntryCount": c["open_entry_count"],\n                    "totalEntryCount": c["total_entry_count"],\n                    "totalOutstanding": format_for_json(c["total_outstanding"]),\n                }\n                for c in trash["customers"]\n            ],\n            "entries": [\n                {\n                    "id": str(e.id),\n                    "customerId": str(e.customer_id),\n                    "description": e.description,\n                    "originalAmount": format_for_json(Money(e.original_amount_cents)),\n                    "deletionReason": e.deletion_reason,\n                }\n                for e in trash["entries"]\n            ],\n        },\n    )\n'
FILES['backend/src/domains/business/loan_book/utils/receipt_builder.py'] = '"""\nReceipt data assembly for the Loan Book -- the backend counterpart to\nthe frontend\'s receiptService.ts.\n\nUses shared.finance.receipts.reference.build_reference() for the\nreference code (already built, already tested -- short, speakable,\nexcludes ambiguous characters) rather than reinventing it here.\n\nDELIBERATELY NO SIGNING/QR HERE EITHER, same reasoning as the frontend\nand as shared/finance/receipts/signing.py\'s own docstring: real signing\nneeds server-held key management that doesn\'t exist yet, and a\nforgeable signature is worse than none. This returns the same\nplain-reference-code receipt the frontend already builds -- the backend\nversion exists so a future server-rendered receipt (e.g. for a web\nshare link) can produce byte-identical content to the mobile app\'s own\nreceipt, not because it does anything the frontend doesn\'t already do.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass\nfrom typing import Optional\n\nfrom src.domains.business.loan_book.services.loan_book_service import LoanEntryView\nfrom src.shared.finance import Money, format_amount\nfrom src.shared.finance.receipts.reference import build_reference\n\n\n@dataclass\nclass ReceiptData:\n    reference_code: str\n    customer_name: str\n    from_label: str\n    sale_date_label: str\n    description: Optional[str]\n    original_amount_label: str\n    amount_paid_label: str\n    outstanding_amount_label: str\n    is_settled: bool\n    is_partly_paid: bool\n\n\ndef build_from_label(owner_first_name: Optional[str]) -> str:\n    """Mirrors the frontend\'s buildFromLabel() exactly -- same fallback,\n    same reasoning: never fabricate a business name that doesn\'t exist\n    yet (no Business Profile feature), always supply what\'s real."""\n    trimmed = (owner_first_name or "").strip()\n    if not trimmed:\n        return "Sent via TRU Connect"\n    return f"{trimmed}\'s shop"\n\n\ndef build_receipt_data(\n    view: LoanEntryView, customer_name: str, owner_first_name: Optional[str] = None\n) -> ReceiptData:\n    original = view.entry.original_amount_cents\n    return ReceiptData(\n        reference_code=build_reference("LB", str(view.entry.id)),\n        customer_name=customer_name,\n        from_label=build_from_label(owner_first_name),\n        # NOT "%-d" -- that flag is Linux/Mac-only and raises ValueError\n        # on Windows strftime, which is what this backend actually runs\n        # on. lstrip("0") gets the same "3 August 2026" (not "03 August\n        # 2026") result portably.\n        sale_date_label=view.entry.sale_date.strftime("%d %B %Y").lstrip("0"),\n        description=view.entry.description,\n        original_amount_label=format_amount(Money(original)),\n        amount_paid_label=format_amount(view.amount_paid),\n        outstanding_amount_label=format_amount(view.outstanding),\n        is_settled=view.entry.is_settled,\n        is_partly_paid=view.amount_paid.is_positive and view.outstanding.is_positive,\n    )\n'
FILES['backend/migrations/versions/c2d3e4f5a6b7_loan_book_tables.py'] = '"""\nloan_book_tables\n\nRevision ID: c2d3e4f5a6b7\nRevises: b1a2c3d4e5f6\nCreate Date: 2026-08-04\n\nVERIFY BEFORE RUNNING: down_revision below assumes b1a2c3d4e5f6\n(security audit_events) is still your most recent applied migration.\nIf any migration has been applied since then, update down_revision to\nthat migration\'s real revision id instead -- `flask db history` or\n`flask db current` will show you the real chain.\n"""\nfrom alembic import op\nimport sqlalchemy as sa\nfrom sqlalchemy.dialects import postgresql\n\nrevision = "c2d3e4f5a6b7"\ndown_revision = "b1a2c3d4e5f6"  # VERIFY -- see docstring above\nbranch_labels = None\ndepends_on = None\n\n\ndef upgrade():\n    op.create_table(\n        "customers",\n        sa.Column("id", postgresql.UUID(as_uuid=True), primary_key=True),\n        sa.Column("business_id", postgresql.UUID(as_uuid=True), sa.ForeignKey("auth.users.id"), nullable=False),\n        sa.Column("name", sa.String(200), nullable=False),\n        sa.Column("phone", sa.String(20), nullable=True),\n        sa.Column("first_recorded_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("last_transaction_at", sa.DateTime(timezone=True), nullable=True),\n        sa.Column("created_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("updated_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("is_deleted", sa.Boolean(), nullable=False, server_default=sa.false()),\n        sa.Column("deleted_at", sa.DateTime(timezone=True), nullable=True),\n        sa.Column("deletion_reason", sa.String(500), nullable=True),\n        schema="business",\n    )\n    op.create_index("ix_customers_business_id", "customers", ["business_id"], schema="business")\n    op.create_index(\n        "ix_customers_business_id_deleted", "customers", ["business_id", "is_deleted"], schema="business"\n    )\n\n    op.create_table(\n        "loan_entries",\n        sa.Column("id", postgresql.UUID(as_uuid=True), primary_key=True),\n        sa.Column("business_id", postgresql.UUID(as_uuid=True), sa.ForeignKey("auth.users.id"), nullable=False),\n        sa.Column(\n            "customer_id", postgresql.UUID(as_uuid=True), sa.ForeignKey("business.customers.id"), nullable=False\n        ),\n        sa.Column("original_amount_cents", sa.BigInteger(), nullable=False),\n        sa.Column("sale_date", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("description", sa.String(500), nullable=True),\n        sa.Column("is_settled", sa.Boolean(), nullable=False, server_default=sa.false()),\n        sa.Column("settled_at", sa.DateTime(timezone=True), nullable=True),\n        sa.Column("created_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("updated_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("is_deleted", sa.Boolean(), nullable=False, server_default=sa.false()),\n        sa.Column("deleted_at", sa.DateTime(timezone=True), nullable=True),\n        sa.Column("deletion_reason", sa.String(500), nullable=True),\n        sa.CheckConstraint("original_amount_cents > 0", name="ck_loan_entries_positive_amount"),\n        schema="business",\n    )\n    op.create_index("ix_loan_entries_business_id", "loan_entries", ["business_id"], schema="business")\n    op.create_index(\n        "ix_loan_entries_business_id_deleted", "loan_entries", ["business_id", "is_deleted"], schema="business"\n    )\n    op.create_index("ix_loan_entries_customer_id", "loan_entries", ["customer_id"], schema="business")\n\n    op.create_table(\n        "payments",\n        sa.Column("id", postgresql.UUID(as_uuid=True), primary_key=True),\n        sa.Column(\n            "loan_entry_id",\n            postgresql.UUID(as_uuid=True),\n            sa.ForeignKey("business.loan_entries.id"),\n            nullable=False,\n        ),\n        sa.Column("amount_cents", sa.BigInteger(), nullable=False),\n        sa.Column("paid_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("note", sa.String(500), nullable=True),\n        sa.Column("created_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("updated_at", sa.DateTime(timezone=True), nullable=False),\n        sa.Column("is_deleted", sa.Boolean(), nullable=False, server_default=sa.false()),\n        sa.Column("deleted_at", sa.DateTime(timezone=True), nullable=True),\n        sa.CheckConstraint("amount_cents > 0", name="ck_payments_positive_amount"),\n        schema="business",\n    )\n    op.create_index("ix_payments_loan_entry_id", "payments", ["loan_entry_id"], schema="business")\n\n    loan_history_event_type = postgresql.ENUM(\n        "sale_created", "payment_recorded", "payment_removed", "entry_deleted", "entry_restored",\n        "customer_created", "customer_deleted", "customer_restored", "receipt_viewed", "receipt_shared",\n        name="loan_history_event_type", schema="business",\n    )\n    # NOT calling .create() explicitly here -- SQLAlchemy already creates\n    # a Postgres ENUM type automatically the first time it\'s used as a\n    # column type inside create_table() below. Calling .create() first\n    # AND using it in create_table() creates the type twice, which fails\n    # with "type already exists" -- caught by actually running this\n    # migration against real Postgres before shipping it.\n\n    op.create_table(\n        "loan_history_events",\n        sa.Column("id", postgresql.UUID(as_uuid=True), primary_key=True),\n        sa.Column("business_id", postgresql.UUID(as_uuid=True), sa.ForeignKey("auth.users.id"), nullable=False),\n        sa.Column("customer_id", postgresql.UUID(as_uuid=True), nullable=False),\n        sa.Column("loan_entry_id", postgresql.UUID(as_uuid=True), nullable=True),\n        sa.Column("event_type", loan_history_event_type, nullable=False),\n        sa.Column("amount_cents", sa.BigInteger(), nullable=True),\n        sa.Column("description", sa.String(500), nullable=True),\n        sa.Column("reason", sa.String(500), nullable=True),\n        sa.Column("metadata", postgresql.JSONB(), nullable=False, server_default="{}"),\n        sa.Column("occurred_at", sa.DateTime(timezone=True), nullable=False),\n        schema="business",\n    )\n    op.create_index("ix_loan_history_business_id", "loan_history_events", ["business_id"], schema="business")\n    op.create_index(\n        "ix_loan_history_business_id_occurred",\n        "loan_history_events", ["business_id", "occurred_at"], schema="business",\n    )\n\n\ndef downgrade():\n    op.drop_table("loan_history_events", schema="business")\n    op.execute("DROP TYPE business.loan_history_event_type")\n    op.drop_table("payments", schema="business")\n    op.drop_table("loan_entries", schema="business")\n    op.drop_table("customers", schema="business")\n'
FILES['backend/tests/domains/business/loan_book/conftest.py'] = '"""\nLoan Book test fixtures -- app/db_session promoted from the pattern\nalready proven in the main tests/conftest.py, plus a make_business_user\nfactory specific to what these tests need (two SEPARATE business owners,\nto prove cross-business isolation).\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nimport pytest\nfrom flask import Flask\n\nfrom src.extensions import db\n\n\n@pytest.fixture()\ndef app():\n    application = Flask(__name__)\n    application.config["SQLALCHEMY_DATABASE_URI"] = "postgresql://postgres:postgres@localhost/loan_backend_test"\n    db.init_app(application)\n    with application.app_context():\n        from src.domains.auth.models.user import User  # noqa: F401\n        from src.domains.business.loan_book.models.customer import Customer  # noqa: F401\n        from src.domains.business.loan_book.models.loan_entry import LoanEntry  # noqa: F401\n        from src.domains.business.loan_book.models.payment import Payment  # noqa: F401\n\n        db.create_all()\n        yield application\n        db.session.remove()\n        db.drop_all()\n\n\n@pytest.fixture()\ndef db_session(app):\n    return db.session\n\n\n@pytest.fixture()\ndef make_business_user(db_session):\n    from src.domains.auth.models.user import User, UserRole\n\n    def _make(email: str):\n        user = User(id=uuid.uuid4(), email=email, password_hash="x", role=UserRole.BUSINESS)\n        db_session.add(user)\n        db_session.commit()\n        return user\n\n    return _make\n'
FILES['backend/tests/domains/business/loan_book/test_ownership.py'] = '"""\nOwnership / IDOR (Insecure Direct Object Reference) tests.\n\nTHE MOST IMPORTANT TEST FILE IN THIS FEATURE. Loan Book is the first\nresource in this whole backend that genuinely NEEDS per-owner isolation\n-- Auth only ever had /me, which is inherently self-scoped and could\nnever actually test "can user A see user B\'s data" because there was\nnothing to see. This is that test, now that a real second resource\nexists.\n\nEvery test in this file follows the same shape: Business A creates real\ndata. Business B -- a completely separate, real business owner -- tries\nto read, modify, or delete it using A\'s REAL id. Every attempt must fail\nidentically to how a non-existent id would fail (LoanBookNotFoundError,\nnever a different error, never a partial success) -- see\nservices/errors.py\'s docstring for why "not yours" and "doesn\'t exist"\nmust be indistinguishable to the caller.\n"""\nfrom __future__ import annotations\n\nimport pytest\n\nfrom src.domains.business.loan_book.services.errors import LoanBookNotFoundError\nfrom src.domains.business.loan_book.services.loan_book_service import LoanBookService\nfrom src.shared.finance import Money\n\n\n@pytest.fixture()\ndef business_a(make_business_user):\n    return make_business_user("business-a@example.com")\n\n\n@pytest.fixture()\ndef business_b(make_business_user):\n    return make_business_user("business-b@example.com")\n\n\n@pytest.fixture()\ndef business_a_customer(business_a):\n    return LoanBookService.create_customer(business_a.id, "Mandla (A\'s customer)", "0783511969")\n\n\n@pytest.fixture()\ndef business_a_entry(business_a, business_a_customer):\n    return LoanBookService.create_entry(\n        business_a.id, business_a_customer.id, Money(50000), description="A\'s private sale"\n    )\n\n\nclass TestCustomerOwnership:\n    def test_business_b_cannot_read_business_a_customer(self, business_b, business_a_customer):\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.get_customer(business_b.id, business_a_customer.id)\n\n    def test_business_b_customer_list_never_includes_business_a_customers(\n        self, business_b, business_a_customer\n    ):\n        """Not just \'direct fetch by ID fails\' -- the LIST endpoint must\n        never leak another business\'s rows either, which is a separate\n        code path from get_by_id() and needs its own proof."""\n        LoanBookService.create_customer(business_b.id, "Business B\'s own customer")\n\n        b_customers = LoanBookService.list_customers(business_b.id)\n        b_customer_ids = {c.id for c in b_customers}\n\n        assert business_a_customer.id not in b_customer_ids\n\n    def test_business_a_can_read_their_own_customer(self, business_a, business_a_customer):\n        """The negative-case tests above are only meaningful alongside\n        this: proving the legitimate owner is NOT accidentally blocked\n        by whatever mechanism blocks everyone else."""\n        found = LoanBookService.get_customer(business_a.id, business_a_customer.id)\n        assert found.id == business_a_customer.id\n\n\nclass TestLoanEntryOwnership:\n    def test_business_b_cannot_read_business_a_entry(self, business_b, business_a_entry):\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.get_entry(business_b.id, business_a_entry.id)\n\n    def test_business_b_entry_list_never_includes_business_a_entries(\n        self, business_a, business_a_entry, business_b\n    ):\n        entries = LoanBookService.list_entries(business_b.id)\n        entry_ids = {v.entry.id for v in entries}\n        assert business_a_entry.id not in entry_ids\n\n    def test_business_b_cannot_pay_business_a_entry(self, business_b, business_a_entry):\n        """The sharpest version of this test: B doesn\'t just try to\n        READ A\'s entry, they try to record a REAL PAYMENT against it\n        using A\'s real entry id. If this ever succeeded, business B\n        could pay down -- or fraudulently mark settled -- a debt they\n        have no relationship to at all."""\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.record_payment(business_b.id, business_a_entry.id, Money(10000))\n\n    def test_business_b_cannot_delete_business_a_entry(self, business_b, business_a_entry):\n        """Even more consequential than reading or paying: can B simply\n        make A\'s real debt record disappear?"""\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.delete_entry(business_b.id, business_a_entry.id, reason="malicious")\n\n    def test_business_b_cannot_create_an_entry_against_business_a_customer(\n        self, business_b, business_a_customer\n    ):\n        """The reverse direction: B supplies A\'s REAL customer_id,\n        trying to attach a new sale to a customer they don\'t own. This\n        must fail exactly like the customer didn\'t exist, because from\n        B\'s authorization perspective, it doesn\'t."""\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.create_entry(business_b.id, business_a_customer.id, Money(1000))\n\n    def test_business_a_can_still_pay_and_delete_their_own_entry(\n        self, business_a, business_a_entry\n    ):\n        """Same principle as the customer-ownership positive test: the\n        isolation mechanism must not accidentally lock out the real\n        owner."""\n        view = LoanBookService.record_payment(business_a.id, business_a_entry.id, Money(10000))\n        assert view.outstanding.minor_units == 40000\n\n        LoanBookService.delete_entry(business_a.id, business_a_entry.id, reason="test cleanup")\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.get_entry(business_a.id, business_a_entry.id)\n\n\nclass TestNotFoundAndNotYoursAreIndistinguishable:\n    """The precise property the whole authorization model rests on: an\n    attacker probing IDs must get IDENTICAL responses whether they\n    guessed a real ID belonging to someone else, or a random ID that\n    was never real at all."""\n\n    def test_genuinely_nonexistent_id_raises_the_same_exception(self, business_b):\n        import uuid\n\n        fake_id = uuid.uuid4()\n        with pytest.raises(LoanBookNotFoundError):\n            LoanBookService.get_customer(business_b.id, fake_id)\n\n    def test_same_exception_type_for_both_cases(self, business_a, business_b, business_a_customer):\n        """Directly compares the exception TYPE and MESSAGE for both\n        scenarios -- they must be identical, not just both happen to be\n        LoanBookNotFoundError with different text that could itself leak\n        information."""\n        import uuid\n\n        errors = []\n        for target_id in (business_a_customer.id, uuid.uuid4()):\n            try:\n                LoanBookService.get_customer(business_b.id, target_id)\n            except LoanBookNotFoundError as exc:\n                errors.append((type(exc), str(exc)))\n\n        assert len(errors) == 2\n        assert errors[0] == errors[1]\n'
FILES['backend/tests/domains/business/loan_book/test_api_ownership.py'] = '"""\nHTTP-level ownership tests -- the pytest version of what was manually\nproven working (see the assistant\'s own verification script during\ndevelopment). Confirms isolation holds through the real Flask route +\nJWT auth stack, not just when LoanBookService is called directly as\nPython functions (see test_ownership.py for that layer).\n"""\nfrom __future__ import annotations\n\nimport pytest\nfrom flask import Flask\nfrom flask_jwt_extended import JWTManager, create_access_token\n\nfrom src.domains.business.loan_book.api.loan_book_routes import loan_book_bp\nfrom src.extensions import db\n\n\n@pytest.fixture()\ndef http_app():\n    application = Flask(__name__)\n    application.config["SQLALCHEMY_DATABASE_URI"] = "postgresql://postgres:postgres@localhost/loan_backend_test"\n    application.config["JWT_SECRET_KEY"] = "test-secret-not-real"\n    application.config["TESTING"] = True\n    db.init_app(application)\n    JWTManager(application)\n    application.register_blueprint(loan_book_bp)\n    with application.app_context():\n        from src.domains.auth.models.user import User  # noqa: F401\n        from src.domains.business.loan_book.models.customer import Customer  # noqa: F401\n        from src.domains.business.loan_book.models.loan_entry import LoanEntry  # noqa: F401\n        from src.domains.business.loan_book.models.payment import Payment  # noqa: F401\n\n        db.create_all()\n        yield application\n        db.session.remove()\n        db.drop_all()\n\n\n@pytest.fixture()\ndef http_client(http_app):\n    return http_app.test_client()\n\n\n@pytest.fixture()\ndef two_businesses_with_a_real_entry(http_app):\n    import uuid\n\n    from src.domains.auth.models.user import User, UserRole\n    from src.domains.business.loan_book.services.loan_book_service import LoanBookService\n    from src.shared.finance import Money\n\n    with http_app.app_context():\n        business_a = User(id=uuid.uuid4(), email="http-a@example.com", password_hash="x", role=UserRole.BUSINESS)\n        business_b = User(id=uuid.uuid4(), email="http-b@example.com", password_hash="x", role=UserRole.BUSINESS)\n        db.session.add_all([business_a, business_b])\n        db.session.commit()\n\n        a_customer = LoanBookService.create_customer(business_a.id, "A\'s customer")\n        a_entry = LoanBookService.create_entry(business_a.id, a_customer.id, Money(75000))\n\n        return {\n            "token_a": create_access_token(identity=str(business_a.id)),\n            "token_b": create_access_token(identity=str(business_b.id)),\n            "entry_id": str(a_entry.id),\n        }\n\n\nclass TestHttpOwnershipIsolation:\n    def test_owner_can_read_their_own_entry(self, http_client, two_businesses_with_a_real_entry):\n        r = http_client.get(\n            f"/api/v1/loan-book/entries/{two_businesses_with_a_real_entry[\'entry_id\']}",\n            headers={"Authorization": f"Bearer {two_businesses_with_a_real_entry[\'token_a\']}"},\n        )\n        assert r.status_code == 200\n        assert r.get_json()["data"]["outstandingAmount"]["minor_units"] == 75000\n\n    def test_other_business_cannot_read_via_real_http(self, http_client, two_businesses_with_a_real_entry):\n        r = http_client.get(\n            f"/api/v1/loan-book/entries/{two_businesses_with_a_real_entry[\'entry_id\']}",\n            headers={"Authorization": f"Bearer {two_businesses_with_a_real_entry[\'token_b\']}"},\n        )\n        assert r.status_code == 404\n\n    def test_other_business_cannot_pay_via_real_http(self, http_client, two_businesses_with_a_real_entry):\n        """The sharpest case: an actual HTTP POST attempting to pay\n        down a debt the caller has no relationship to at all."""\n        r = http_client.post(\n            f"/api/v1/loan-book/entries/{two_businesses_with_a_real_entry[\'entry_id\']}/payments",\n            json={"amountCents": 10000},\n            headers={"Authorization": f"Bearer {two_businesses_with_a_real_entry[\'token_b\']}"},\n        )\n        assert r.status_code == 404\n\n    def test_other_business_cannot_delete_via_real_http(self, http_client, two_businesses_with_a_real_entry):\n        r = http_client.delete(\n            f"/api/v1/loan-book/entries/{two_businesses_with_a_real_entry[\'entry_id\']}",\n            headers={"Authorization": f"Bearer {two_businesses_with_a_real_entry[\'token_b\']}"},\n        )\n        assert r.status_code == 404\n\n    def test_no_token_is_401(self, http_client, two_businesses_with_a_real_entry):\n        r = http_client.get(f"/api/v1/loan-book/entries/{two_businesses_with_a_real_entry[\'entry_id\']}")\n        assert r.status_code == 401\n'

README = '# Loan Book Backend\n\nFull backend implementation: models, repositories, service layer\n(Finance Engine-integrated), schemas, API routes, migration, and 16\ntests -- 11 at the service layer, 5 over real HTTP -- all proving\ncross-business ownership isolation, the core requirement for this\nfeature\'s first real multi-tenant resource.\n\n## Folder shape (per your explicit decision)\n\nMatches Auth\'s simpler structure -- no commands/events/queries/\nalgorithms/validators. Money math delegates entirely to\nshared/finance/ (already built); validation lives in schemas/, matching\nAuth\'s own convention.\n\n```\nbusiness/loan_book/\n├── api/loan_book_routes.py\n├── models/{customer,loan_entry,payment,loan_history_event}.py\n├── repositories/{customer,loan,payment,history}_repository.py\n├── schemas/loan_book_schemas.py\n├── services/{errors,loan_book_service}.py\n└── utils/receipt_builder.py\n```\n\n## REQUIRED manual steps before this works\n\n### 1. Register the blueprint in src/__init__.py\n\n```python\ndef _register_blueprints(app: Flask) -> None:\n    from src.api import api_bp\n    app.register_blueprint(api_bp, url_prefix="/api/v1")\n\n    from src.domains.platform.api.reset_password_routes import reset_password_bp\n    app.register_blueprint(reset_password_bp)\n\n    # ADD THIS:\n    from src.domains.business.loan_book.api.loan_book_routes import loan_book_bp\n    app.register_blueprint(loan_book_bp)\n```\n\n### 2. Verify the migration\'s down_revision\n\n`migrations/versions/c2d3e4f5a6b7_loan_book_tables.py` assumes\n`b1a2c3d4e5f6` (security audit_events) is your most recently applied\nmigration. Check with:\n```\nflask db current\n```\nIf anything else has been applied since, update `down_revision` in the\nmigration file to match the real chain -- otherwise `flask db upgrade`\nwill fail or apply out of order.\n\n### 3. Verify the `fully_authenticated` import path\n\n`api/loan_book_routes.py` imports:\n```python\nfrom src.domains.auth.decorators import fully_authenticated\n```\nThis name is confirmed real (referenced by name in test_auth.py\'s own\ndocstring), but its exact file location was never directly seen while\nbuilding this. If your real decorator lives elsewhere (e.g.\n`src.domains.auth.utils.decorators`), fix this one import line -- nothing\nelse in the routes file depends on where it\'s defined.\n\n### 4. Verify BaseModel\'s real columns\n\nEvery model assumes `src.core.base_model.BaseModel` provides:\n`id` (UUID, default uuid4), `created_at`, `updated_at`, `is_deleted`\n(default False), `deleted_at`. This is inferred from usage patterns\nacross earlier work in this project, never directly confirmed against\nthe real file. If it differs, the mismatch will surface immediately as\nan import or migration error -- easy to spot, not silent.\n\n## Run the tests (once the above is done)\n\n```\npython -m pytest tests/domains/business/loan_book/ -v\n```\n\nExpect 16 passing. These need `TEST_DATABASE_URL` set and the\n`business`/`auth` schemas already created -- same one-time setup as\nevery other test suite in this project (see tests/TESTING.md).\n\n## What\'s proven, and how\n\n**Ownership isolation (the core deliverable):** two separate real\nbusiness owners, real JWTs, real HTTP requests. Business B, with their\nown genuinely valid token, gets 404 attempting to read, pay, or delete\nBusiness A\'s real entry using A\'s real ID -- including the sharpest\ncase, an actual POST attempting to record a payment against a debt B\nhas no relationship to. Proven at both the service layer (calling\nLoanBookService directly) and the full HTTP/JWT stack, run multiple\ntimes for stability.\n\n**Cascade delete/restore:** the exact adversarial scenario already\nproven on the frontend -- delete one entry independently, then delete\nthe whole customer (cascading the remaining entries), then restore the\ncustomer -- correctly restores only the cascaded entries, and the\nindependently-deleted one correctly reappears on its own, with the same\ntimestamp-discrimination logic as the frontend\'s MockDataRepository.\n\n**Money math:** every calculation runs through the real, separately-\ntested shared/finance/ engine -- no parallel money logic exists in this\nfeature. R500 sale, R200 payment, confirmed R300 outstanding via real\nHTTP response.\n\n**The migration itself:** run both upgrade() and downgrade() through\nAlembic\'s real Operations API against real Postgres, not just syntax-\nchecked. Caught and fixed a genuine bug this way -- the Postgres ENUM\ntype for loan_history_event_type was being created twice (once\nexplicitly, once automatically by create_table()), which would have\nfailed the very first real `flask db upgrade`.\n\n## Two other real bugs caught by actually running the code\n\n1. `utils/receipt_builder.py` used `strftime("%-d %B %Y")` -- the `-d`\n   flag is Linux/Mac-only and raises ValueError on Windows, which is\n   what this backend actually runs on. Fixed to a portable\n   `strftime("%d %B %Y").lstrip("0")`, verified against every day 1-31.\n2. The same file had a leftover `__import__(...)` hack from drafting,\n   replaced with a proper top-level import.\n\n## Architecture decision made explicit, not silent\n\n`LoanHistoryEvent` is Loan Book\'s OWN event log, not merged into the\nshared Auth audit system (`shared/audit/`) -- even though the pattern is\nstructurally identical (append-only, one row per event). This mirrors\nthe frontend\'s own identical decision, for the identical reason: the\nreal internal shape of `shared/audit`\'s `AuditEventName` enum and its\nreserved-but-empty `event_types/business.py` placeholder was never\ndirectly seen while building this, and guessing at how a new domain\nplugs into an existing system risks repeating the exact costly mistake\nthat happened earlier in this project with `JobExecutionOutcome`\'s\nfields. This is a natural future merge, not an oversight -- revisit\ndeliberately, with both real systems visible at once, when it\'s time.\n'
