def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", required=True, help="Path to the TRU_Connect repo root")
    parser.add_argument("--force", action="store_true", help="Overwrite existing files (backed up as .bak)")
    parser.add_argument("--dry-run", action="store_true", help="Preview without writing")
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    if not root.exists():
        print(f"Root path does not exist: {root}", file=sys.stderr)
        sys.exit(1)

    created, replaced, skipped = [], [], []
    for rel_path, content in FILES.items():
        target = root / rel_path
        exists = target.exists()
        if exists and not args.force:
            skipped.append(rel_path)
            continue
        if not args.dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
            if exists:
                target.with_suffix(target.suffix + ".bak").write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            target.write_text(content, encoding="utf-8")
        (replaced if exists else created).append(rel_path)

    verb = "Would create" if args.dry_run else "Created"
    print(f"\n{verb} {len(created)} file(s):")
    for p in created:
        print(f"  + {p}")
    if replaced:
        print(f"\nReplaced {len(replaced)} file(s) (backed up as .bak):")
        for p in replaced:
            print(f"  ~ {p}")
    if skipped:
        print(f"\nSkipped {len(skipped)} existing file(s) (use --force):")
        for p in skipped:
            print(f"  - {p}")

    print("""
====================================================================
REQUIRED NEXT STEPS -- this will NOT work until you do these
====================================================================
1. Register the blueprint in src/__init__.py (see the README this
   script created for the exact code).

2. Verify the migration's down_revision against `flask db current`.

3. Verify the fully_authenticated import path in loan_book_routes.py.

4. Verify BaseModel's real columns match what these models assume.

Then:
   flask db upgrade
   python -m pytest tests/domains/business/loan_book/ -v

Read backend/src/domains/business/loan_book/LOAN_BOOK_BACKEND_README.md
for full details, including two real bugs caught by actually running
this code (a Windows-incompatible date format, a double-CREATE-TYPE
migration bug) and the deliberate decision to keep Loan Book's history
log separate from the shared Auth audit system for now.
""")


if __name__ == "__main__":
    main()